create type "public"."broker_type" as enum ('broker_site', 'google', 'bing', 'yahoo', 'duckduckgo');

create type "public"."pricing_type" as enum ('one_year', 'two_year', 'annual_recurring');

create type "public"."removal_status" as enum ('queued', 'in_progress', 'need_customer_action', 'completed', 'failed');

create type "public"."search_status" as enum ('queued', 'in_progress', 'completed', 'failed');

create table "public"."auth_group" (
    "id" integer generated by default as identity not null,
    "name" character varying(150) not null
);


create table "public"."auth_group_permissions" (
    "id" bigint generated by default as identity not null,
    "group_id" integer not null,
    "permission_id" integer not null
);


create table "public"."auth_permission" (
    "id" integer generated by default as identity not null,
    "name" character varying(255) not null,
    "content_type_id" integer not null,
    "codename" character varying(100) not null
);


create table "public"."auth_user" (
    "id" integer generated by default as identity not null,
    "password" character varying(128) not null,
    "last_login" timestamp with time zone,
    "is_superuser" boolean not null,
    "username" character varying(150) not null,
    "first_name" character varying(150) not null,
    "last_name" character varying(150) not null,
    "email" character varying(254) not null,
    "is_staff" boolean not null,
    "is_active" boolean not null,
    "date_joined" timestamp with time zone not null
);


create table "public"."auth_user_groups" (
    "id" bigint generated by default as identity not null,
    "user_id" integer not null,
    "group_id" integer not null
);


create table "public"."auth_user_user_permissions" (
    "id" bigint generated by default as identity not null,
    "user_id" integer not null,
    "permission_id" integer not null
);


create table "public"."brokers" (
    "id" bigint generated by default as identity not null,
    "name" text,
    "site_url" text,
    "enable_scraping" boolean default false,
    "scraping_url" text,
    "optout_url" text,
    "need_captcha" boolean default false,
    "need_vpn" boolean default false,
    "notes" text
);


alter table "public"."brokers" enable row level security;

create table "public"."django_admin_log" (
    "id" integer generated by default as identity not null,
    "action_time" timestamp with time zone not null,
    "object_id" text,
    "object_repr" character varying(200) not null,
    "action_flag" smallint not null,
    "change_message" text not null,
    "content_type_id" integer,
    "user_id" integer not null
);


create table "public"."django_content_type" (
    "id" integer generated by default as identity not null,
    "app_label" character varying(100) not null,
    "model" character varying(100) not null
);


create table "public"."django_migrations" (
    "id" bigint generated by default as identity not null,
    "app" character varying(255) not null,
    "name" character varying(255) not null,
    "applied" timestamp with time zone not null
);


create table "public"."django_session" (
    "session_key" character varying(40) not null,
    "session_data" text not null,
    "expire_date" timestamp with time zone not null
);


create table "public"."pricing_plans" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "profile_id" bigint,
    "type" pricing_type
);


alter table "public"."pricing_plans" enable row level security;

create table "public"."profiles" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "user_id" uuid,
    "first_name" text,
    "last_name" text,
    "birth_date" date,
    "gender" character varying default ''::character varying,
    "city" text,
    "state" text
);


alter table "public"."profiles" enable row level security;

create table "public"."searches" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "profile_id" bigint,
    "broker_type" broker_type,
    "broker_id" bigint,
    "search_status" search_status,
    "search_result" jsonb,
    "removal_status" removal_status,
    "removal_note" text
);


alter table "public"."searches" enable row level security;

create table "public"."users" (
    "id" uuid not null,
    "stripe_customer_id" text
);


alter table "public"."users" enable row level security;

