CREATE OR REPLACE FUNCTION public.create_search_queue()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$BEGIN
  INSERT INTO searches (profile_id, broker_type, broker_id, status)
  SELECT NEW.id, 'broker_site', brokers.id, 'queued'
  FROM brokers;

  INSERT INTO searches (profile_id, broker_type, status)
  VALUES (NEW.id, 'google', 'queued');

  RETURN NEW;
END;$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.users (id)
  values (new.id);
  return new;
end;
$function$
;

