create policy "Enable read for authenticated users only"
on "public"."brokers"
as permissive
for select
to authenticated
using (true);


create policy "Enable users to view their own data only"
on "public"."pricing_plans"
as permissive
for select
to authenticated
using ((( SELECT auth.uid() AS uid) IN ( SELECT profiles.user_id
   FROM profiles
  WHERE (profiles.id = pricing_plans.profile_id))));


create policy "Enable insert for users based on user_id"
on "public"."profiles"
as permissive
for insert
to public
with check ((( SELECT auth.uid() AS uid) = user_id));


create policy "Enable users to view their own data only"
on "public"."profiles"
as permissive
for select
to authenticated
using ((( SELECT auth.uid() AS uid) = user_id));


create policy "Enable users to view their own data only"
on "public"."searches"
as permissive
for select
to authenticated
using ((( SELECT auth.uid() AS uid) IN ( SELECT profiles.user_id
   FROM profiles
  WHERE (profiles.id = searches.profile_id))));


create policy "Enable users to view their own data only"
on "public"."users"
as permissive
for select
to authenticated
using ((( SELECT auth.uid() AS uid) = id));


CREATE TRIGGER handle_new_user AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
CREATE TRIGGER create_search_queue AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION create_search_queue();

